using FluentValidation;
namespace OAS.Application.Accounting.PaymentVouchers.Commands.UpdatePaymentVoucher;
public sealed class UpdatePaymentVoucherCommandValidator:AbstractValidator<UpdatePaymentVoucherCommand>{public UpdatePaymentVoucherCommandValidator(){RuleFor(x=>x.Id).NotEmpty();RuleFor(x=>x.Data.RowVersion).NotEmpty();RuleFor(x=>x.Data.Lines).NotEmpty().WithErrorCode("payment_voucher_lines_required");RuleForEach(x=>x.Data.Lines).ChildRules(l=>{l.RuleFor(x=>x.CurrencyId).NotEmpty();l.RuleFor(x=>x.Amount).GreaterThan(0);l.RuleFor(x=>x.ExchangeRate).GreaterThan(0).When(x=>x.ExchangeRate.HasValue);});}}
